mapper.select:
select
ptr.id as id,
ptr.create_time as createTime,
ptr.electricity as electricity,
ptr.voltage as voltage
from
tech_capp_craft_product_pass_task_record as ptr

    ptr.bool_delete_enum = 0
    and ptr.tech_capp_craft_product_pass_task_id = #{passId}
    
        and ptr.electricity between #{ratedMinElectricity} and #{ratedMaxElectricity}
        and ptr.voltage between #{ratedMinVoltage} and #{ratedMaxVoltage}
    
    
        and (
        ptr.electricity not between #{ratedMinElectricity} and #{ratedMaxElectricity}
        or ptr.voltage not between #{ratedMinVoltage} and #{ratedMaxVoltage}
        )
    

order by ptr.create_time
